"""A least-recently-used cache with optional time-to-live (TTL) expiry."""
import time
from collections import OrderedDict


class _UseDefault:
    def __repr__(self):
        return "USE_DEFAULT"


USE_DEFAULT = _UseDefault()


def _check_ttl(ttl):
    # None means "never expires"; anything else must be strictly positive.
    # `not ttl > 0` also rejects NaN.
    if ttl is not None and not ttl > 0:
        raise ValueError("ttl must be greater than 0 or None")


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        _check_ttl(ttl)
        self.capacity = capacity
        self.ttl = ttl
        self._clock = clock
        # key -> (value, stored_at, ttl); ttl None means never expires.
        self._items = OrderedDict()

    def _expired(self, entry, now):
        _, stored_at, ttl = entry
        return ttl is not None and now - stored_at >= ttl

    def _live_entry(self, key, now):
        """Return the entry for key if it is present and not expired, else None."""
        entry = self._items.get(key)
        if entry is None or self._expired(entry, now):
            return None
        return entry

    def _purge_expired(self, now):
        expired = [k for k, e in self._items.items() if self._expired(e, now)]
        for k in expired:
            del self._items[k]

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used."""
        entry = self._live_entry(key, self._clock())
        if entry is None:
            return default
        self._items.move_to_end(key)
        return entry[0]

    def peek(self, key, default=None):
        """Return the value without touching the order."""
        entry = self._live_entry(key, self._clock())
        if entry is None:
            return default
        return entry[0]

    def put(self, key, value, ttl=USE_DEFAULT):
        if ttl is USE_DEFAULT:
            ttl = self.ttl
        else:
            _check_ttl(ttl)
        now = self._clock()
        # Expired entries go first, so they never push out a live entry.
        self._purge_expired(now)
        if key in self._items:
            self._items.move_to_end(key)
        elif len(self._items) >= self.capacity:
            self._items.popitem(last=False)
        self._items[key] = (value, now, ttl)

    def keys(self):
        """Live keys from least to most recently used."""
        now = self._clock()
        return [k for k, e in self._items.items() if not self._expired(e, now)]

    def __contains__(self, key):
        return self._live_entry(key, self._clock()) is not None

    def __len__(self):
        now = self._clock()
        return sum(1 for e in self._items.values() if not self._expired(e, now))
